<template>
  <div class="page-heading"><h1 class="page-title">今日需回访</h1><el-button @click="load">刷新</el-button></div>
  <div class="summary-grid"><article><span>今日待回访</span><strong>{{ data.counts.today }}</strong></article><article class="danger"><span>已逾期未回访</span><strong>{{ data.counts.overdue }}</strong></article><article class="success"><span>今日已完成回访</span><strong>{{ data.counts.completed }}</strong></article></div>
  <section class="content-panel"><el-tabs v-model="tab"><el-tab-pane :label="`今日待回访 ${data.counts.today}`" name="today"/><el-tab-pane :label="`逾期未回访 ${data.counts.overdue}`" name="overdue"/></el-tabs><div class="table-scroll"><el-table :data="visibleCallbacks" v-loading="loading" row-key="id" @row-click="openDetail"><el-table-column prop="name" label="姓名" min-width="110"/><el-table-column prop="phone" label="电话" width="130"/><el-table-column prop="project.name" label="项目" min-width="120"/><el-table-column prop="channelSource" label="渠道" min-width="110"/><el-table-column label="状态" width="100"><template #default="{row}"><el-tag>{{row.status.name}}</el-tag></template></el-table-column><el-table-column label="负责人" width="120"><template #default="{row}">{{row.owner.nickname||row.owner.username}}</template></el-table-column><el-table-column label="下次回访时间" width="180"><template #default="{row}"><strong :class="{overdue:row.overdue}">{{fmt(row.nextFollowUpAt)}}</strong></template></el-table-column><el-table-column label="最近跟进" width="180"><template #default="{row}">{{fmt(row.lastFollowUpAt)}}</template></el-table-column><el-table-column label="操作" width="100" fixed="right"><template #default="{row}"><el-button link type="primary" @click.stop="openDetail(row)">查看详情</el-button></template></el-table-column></el-table></div><div class="mobile-callback-list" v-loading="loading"><article v-for="row in visibleCallbacks" :key="row.id" class="mobile-callback-card"><div class="callback-card-head"><strong>{{ row.name }}</strong><span>{{ row.phoneMasked || row.phone }}</span><el-tag size="small" :type="row.overdue ? 'danger' : 'warning'">{{ row.status?.name || '—' }}</el-tag></div><div class="callback-due" :class="{ overdue: row.overdue }"><span>{{ row.overdue ? '已逾期' : '回访时间' }}</span><strong>{{ fmt(row.nextFollowUpAt) }}</strong></div><div class="callback-details"><div><span>项目</span><strong>{{ row.project?.name || '—' }}</strong></div><div><span>负责人</span><strong>{{ row.owner?.nickname || row.owner?.username || '—' }}</strong></div><div><span>渠道</span><strong>{{ row.channelSource || '—' }}</strong></div><div><span>最近跟进</span><strong>{{ fmt(row.lastFollowUpAt) }}</strong></div></div><div class="callback-actions"><el-button @click="openDetail(row)">查看详情</el-button><el-button v-if="canFollowUp" type="primary" @click="quickFollowUp(row)">新增跟进</el-button></div></article><el-empty v-if="!loading && !visibleCallbacks.length" description="暂无待回访表单" /></div></section>
  <el-drawer v-model="detailVisible" title="回访详情" size="min(720px, 94vw)"><template v-if="detail"><el-descriptions :column="detailColumns" border><el-descriptions-item label="姓名">{{detail.name}}</el-descriptions-item><el-descriptions-item label="电话">{{detail.phone}}</el-descriptions-item><el-descriptions-item label="项目">{{detail.project.name}}</el-descriptions-item><el-descriptions-item label="渠道">{{detail.channelSource}}</el-descriptions-item><el-descriptions-item label="状态">{{detail.status.name}}</el-descriptions-item><el-descriptions-item label="负责人">{{detail.owner.nickname||detail.owner.username}}</el-descriptions-item><el-descriptions-item label="下次回访">{{fmt(detail.nextFollowUpAt)}}</el-descriptions-item></el-descriptions><div class="follow-heading"><h3>跟进回访记录</h3><el-button v-if="canFollowUp" type="primary" @click="followVisible=true">新增跟进</el-button></div><el-timeline v-if="detail.followUps?.length"><el-timeline-item v-for="item in detail.followUps" :key="item.id" :timestamp="fmt(item.createdAt)" placement="top"><p>{{item.content}}</p><small>{{item.createdBy?.nickname||item.createdBy?.username}}<span v-if="item.resultStatus"> · {{item.resultStatus.name}}</span></small></el-timeline-item></el-timeline><el-empty v-else description="暂无跟进记录" /></template></el-drawer>
  <el-dialog v-model="followVisible" title="新增跟进记录" width="min(520px, 94vw)"><el-form label-position="top"><el-form-item label="跟进内容" required><el-input v-model="follow.content" type="textarea" :rows="4" /></el-form-item><el-form-item label="跟进结果状态"><el-select v-model="follow.resultStatusId" clearable><el-option v-for="item in statuses" :key="item.id" :label="item.name" :value="item.id" /></el-select></el-form-item><el-form-item label="下次回访时间"><el-date-picker v-model="follow.nextFollowUpAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss.SSSZ" clearable /></el-form-item></el-form><template #footer><el-button @click="followVisible=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveFollowUp">保存跟进</el-button></template></el-dialog>
</template>
<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue';
import { ElMessage } from 'element-plus';
import { addConsultationFollowUp, getConsultation, getConsultationCallbacks, getConsultationMetadata, type ConsultationFormItem } from '../api/admin';
import { useAuthStore } from '../stores/auth';
const auth=useAuthStore();const canFollowUp=computed(()=>auth.hasPermission('CONSULTATION_FOLLOW_UP'));const loading=ref(false);const saving=ref(false);const tab=ref('today');const detailVisible=ref(false);const followVisible=ref(false);const detail=ref<ConsultationFormItem|null>(null);const statuses=ref<Array<{id:string;name:string}>>([]);const detailColumns=ref(window.innerWidth<700?1:2);const follow=reactive({content:'',resultStatusId:'',nextFollowUpAt:''});
const data=reactive<{counts:{today:number;overdue:number;completed:number};today:ConsultationFormItem[];overdue:ConsultationFormItem[]}>({counts:{today:0,overdue:0,completed:0},today:[],overdue:[]});
const visibleCallbacks=computed(()=>tab.value==='today'?data.today:data.overdue);
async function load(){loading.value=true;try{Object.assign(data,await getConsultationCallbacks())}finally{loading.value=false}}
async function openDetail(row:ConsultationFormItem){detailVisible.value=true;detail.value=null;try{detail.value=await getConsultation(row.id);follow.content='';follow.resultStatusId='';follow.nextFollowUpAt=detail.value.nextFollowUpAt||'';}catch{ElMessage.error('回访详情加载失败');detailVisible.value=false;}}
async function quickFollowUp(row:ConsultationFormItem){await openDetail(row);if(detail.value)followVisible.value=true}
async function saveFollowUp(){if(!detail.value||!canFollowUp.value)return;if(!follow.content.trim())return ElMessage.warning('请填写跟进内容');saving.value=true;try{await addConsultationFollowUp(detail.value.id,{content:follow.content.trim(),resultStatusId:follow.resultStatusId||undefined,nextFollowUpAt:follow.nextFollowUpAt||null});detail.value=await getConsultation(detail.value.id);followVisible.value=false;await load();ElMessage.success('跟进记录已保存');}catch{ElMessage.error('保存跟进失败');}finally{saving.value=false;}}
function fmt(value?:string){return value?new Date(value).toLocaleString('zh-CN',{hour12:false}):'—'}
onMounted(()=>{void load();if(canFollowUp.value){void getConsultationMetadata().then(result=>{statuses.value=result.statuses.filter(item=>item.enabled)}).catch(()=>{statuses.value=[]});}});
</script>
<style scoped>.page-heading{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:12px}.summary-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin-bottom:12px}.summary-grid article{padding:16px;border:1px solid var(--admin-border);border-radius:10px;background:#fff}.summary-grid span{display:block;color:var(--admin-text-muted)}.summary-grid strong{display:block;margin-top:6px;color:var(--admin-primary);font-size:28px}.summary-grid .danger strong,.overdue{color:#c45656}.summary-grid .success strong{color:#56836c}.table-scroll{min-width:0;overflow-x:auto}.table-scroll :deep(.el-table){min-width:960px}.follow-heading{display:flex;justify-content:space-between;align-items:center;gap:10px;margin:20px 0 12px}.follow-heading h3{margin:0}.el-timeline p{margin:0 0 5px;overflow-wrap:anywhere}.el-timeline small{color:var(--admin-text-muted)}@media(max-width:700px){.summary-grid{gap:6px}.summary-grid article{padding:10px 8px}.summary-grid span{font-size:12px}.summary-grid strong{font-size:22px}.page-heading{flex-wrap:wrap}}</style>
<style scoped>
.mobile-callback-list{display:none}
@media(max-width:700px){
  .summary-grid{grid-template-columns:repeat(3,minmax(0,1fr));gap:6px}
  .summary-grid article{min-width:0;min-height:78px;padding:10px 8px}
  .summary-grid span{font-size:11px;line-height:1.3;overflow-wrap:anywhere}
  .summary-grid strong{font-size:21px;line-height:1.1}
  .table-scroll{display:none}
  .mobile-callback-list{display:grid;gap:10px;min-width:0}
  .mobile-callback-card{min-width:0;padding:14px;border:1px solid var(--admin-border);border-radius:14px;background:#fff;box-shadow:0 2px 8px rgba(18,45,80,.04)}
  .callback-card-head{display:flex;align-items:center;gap:8px;min-width:0;flex-wrap:wrap}
  .callback-card-head strong{font-size:16px;overflow-wrap:anywhere}
  .callback-card-head span{font-size:13px;color:var(--admin-text-muted);white-space:nowrap}
  .callback-card-head :deep(.el-tag){margin-left:auto;max-width:42%;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
  .callback-due{display:flex;justify-content:space-between;align-items:center;gap:10px;margin-top:12px;padding:10px 12px;border-radius:9px;background:#f4f8ff;font-size:13px}
  .callback-due.overdue{background:#fff2f0}
  .callback-due strong{font-size:14px;overflow-wrap:anywhere;text-align:right}
  .callback-details{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin:14px 0}
  .callback-details>div{display:grid;gap:3px;min-width:0}
  .callback-details span{font-size:12px;color:var(--admin-text-muted)}
  .callback-details strong{font-size:13px;font-weight:500;overflow-wrap:anywhere}
  .callback-actions{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}
  .callback-actions :deep(.el-button){width:100%;min-height:42px;margin:0}
  .callback-actions :deep(.el-button:only-child){grid-column:1/-1}
  .follow-heading{align-items:flex-start}
}
</style>
